import { getJson } from '../../api/http';
import { claimsKey } from '../claims/claimsQuery';

/** A person's plan: `amount` with two decimals, `start` and `end` yyyy-mm-dd, a DRAFT claim every `every` days, or (`every` 0)
 *  on day `day` (1 to 31) of every month; `generated` is how many claims it has made so far; `nextDates`
 *  its first five dates after the sheet's today and on or before its end, comma and space separated. */
export type Plan = { id: number; personId: number; amount: string; start: string; every: number; end: string; generated: number; day: number; nextDates: string };

/** Under the claims' key, so whatever re-reads the claims (a generate, a re-load of the sheet) re-reads the plans too. */
export const plansKey = (sheetId: string) => [...claimsKey(sheetId), 'plans'] as const;

/** Every plan on the sheet, in the order added. */
export const plansQuery = (sheetId: string) => ({
  queryKey: plansKey(sheetId),
  queryFn: () => getJson<Plan[]>(`/api/sheets/${encodeURIComponent(sheetId)}/plans`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsKey } from '../claims/claimsQuery';
import { peopleKey } from '../people/peopleQuery';
import { useUser } from '../session/useUser';
import { plansKey, plansQuery } from './plansQuery';
import type { Plan } from './plansQuery';

type PlanBody = { amount: string; start: string; every: string; day: string; end: string };

/**
 * The person's plans, each with how many claims it has made so far, and the form a plan is added through: an amount,
 * a start date, every N days (a whole number, at least 1) or a day of the month (1 to 31, a day beyond the month's length
 * on its last day) and an end date (a blank date is the sheet's today). An end
 * before the start, or a bad amount or interval, is refused with the row's `plan-error`.
 */
function PersonPlans({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const plans = (useQuery(plansQuery(sheetId)).data ?? []).filter((p) => p.personId === personId);
